const response = $input.first().json;

const content = response.choices?.[0]?.message?.content;

if (typeof content !== 'string' || !content.trim()) {
  throw new Error('Groq returned an empty response');
}

let result;

try {
  result = JSON.parse(content);
} catch {
  throw new Error('Groq response is not valid JSON');
}

if (!Array.isArray(result.components) || result.components.length === 0) {
  throw new Error('AI result must contain components');
}

if (!Array.isArray(result.assumptions)) {
  throw new Error('AI result must contain assumptions');
}

function validateBoolean(value, field) {
  if (typeof value !== 'boolean') {
    throw new Error(`${field} must be a boolean`);
  }
  return value;
}

const components = result.components.map((component, index) => {
  const prefix = `components[${index}]`;

  if (!component.hpa || typeof component.hpa !== 'object') {
    throw new Error(`${prefix}.hpa is missing`);
  }

  if (!component.ingress || typeof component.ingress !== 'object') {
    throw new Error(`${prefix}.ingress is missing`);
  }

  validateBoolean(component.hpa.enabled, `${prefix}.hpa.enabled`);
  validateBoolean(component.ingress.enabled, `${prefix}.ingress.enabled`);
  validateBoolean(component.ingress.tls, `${prefix}.ingress.tls`);

  return component;
});

return [{
  json: {
    components,
    assumptions: result.assumptions
  }
}];
